package com.example.billing.service;
import static com.example.billing.api.Contracts.*; import com.example.billing.domain.*; import com.example.billing.persistence.Repositories.*; import java.util.*; import java.util.regex.Pattern; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class CatalogService { private static final Pattern CURRENCY=Pattern.compile("^[A-Z]{3}$");private final ProductRepository products;private final PricePlanRepository plans;public CatalogService(ProductRepository p,PricePlanRepository pp){products=p;plans=pp;} public ProductResponse createProduct(CreateProductRequest r){var x=new Product();x.id=UUID.randomUUID();x.name=req(r.name());x.description=req(r.description());x.active=r.active();return ProductResponse.from(products.save(x));} @Transactional(readOnly=true) public ProductResponse getProduct(UUID id){return products.findById(id).map(ProductResponse::from).orElse(null);} @Transactional(readOnly=true) public List<ProductResponse> listProducts(){return products.findAllByOrderByNameAscIdAsc().stream().map(ProductResponse::from).toList();} public ProductResponse updateProduct(UUID id,CreateProductRequest r){var x=products.findById(id).orElse(null);if(x==null)return null;x.name=req(r.name());x.description=req(r.description());x.active=r.active();return ProductResponse.from(x);} public ProductResponse deactivateProduct(UUID id){var x=products.findById(id).orElse(null);if(x==null)return null;x.active=false;return ProductResponse.from(x);} public PricePlanResponse createPlan(CreatePricePlanRequest r){ensureProduct(r.productId());var x=new PricePlan();x.id=UUID.randomUUID();apply(x,r);x.active=true;return PricePlanResponse.from(plans.save(x));} @Transactional(readOnly=true) public PricePlanResponse getPlan(UUID id){return plans.findById(id).map(PricePlanResponse::from).orElse(null);} @Transactional(readOnly=true) public List<PricePlanResponse> listPlans(){return plans.findAllByOrderByProductIdAscBillingTypeAscIdAsc().stream().map(PricePlanResponse::from).toList();} public PricePlanResponse updatePlan(UUID id,CreatePricePlanRequest r){var x=plans.findById(id).orElse(null);if(x==null)return null;ensureProduct(r.productId());apply(x,r);return PricePlanResponse.from(x);} public PricePlanResponse deactivatePlan(UUID id){var x=plans.findById(id).orElse(null);if(x==null)return null;x.active=false;return PricePlanResponse.from(x);} private void ensureProduct(UUID id){if(products.findById(id).filter(x->x.active).isEmpty())throw new IllegalStateException("Product does not exist or is not active.");} private static void apply(PricePlan x,CreatePricePlanRequest r){if(r.amount()==null||r.amount().signum()<0)throw new IllegalArgumentException("Amount cannot be negative.");x.productId=r.productId();x.billingType=req(r.billingType());x.amount=r.amount();x.currency=req(r.currency()).toUpperCase(Locale.ROOT);if(!CURRENCY.matcher(x.currency).matches())throw new IllegalArgumentException("Currency must be a three-letter ISO code.");x.billingInterval=req(r.billingInterval());x.usageUnit=opt(r.usageUnit());} static String req(String s){if(s==null||s.isBlank())throw new IllegalArgumentException("Value cannot be empty.");return s.trim();}static String opt(String s){return s==null||s.isBlank()?null:s.trim();} }
